PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?employee a pv:Employee ;
            pv:name "Sabrina" ;
            pv:memberOf prodi:Marketing ;
            pv:email ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?agent a pv:Agent ;
           pv:areaOfExpertise ?category .
  ?category rdfs:label "Transistors" .
  BIND(?agent AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?department a pv:Department ;
              pv:name "Data Services" ;
              pv:hasManager ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?sensorSwitch) AS ?result) WHERE {
  ?sensorSwitch a pv:Hardware ; pv:name "Sensor Switch" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?agent a pv:Employee ;
           pv:areaOfExpertise prodi:prod-cat-Network ;
           pv:memberOf prodi:dept-Marketing ;
           pv:name ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?employee a pv:Employee ;
              pv:areaOfExpertise prodi:prod-cat-Transducer ;
              pv:memberOf ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?supplier) AS ?result) WHERE {
  ?supplier a pv:Supplier ;
              pv:country "France" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?supplier a pv:Supplier ;
            pv:addressLocality "Toulouse" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?supplier a pv:Supplier ;
              pv:addressLocality "Toulouse" .
  BIND(?supplier AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?product a pv:Hardware ;
           pv:hasCategory prodi:prod-cat-Oscillator ;
           pv:price ?price .
  ?price pv:amount ?amount .
} ORDER BY ASC(?amount) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price .
  ?price pv:amount ?amount .
} ORDER BY DESC(?amount) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?coil a pv:Hardware ;
          pv:name ?result ;
          pv:weight_g ?weight ;
          pv:width_mm ?width ;
          pv:depth_mm ?depth .
  FILTER(?width * ?depth <= 15 * 15)
} ORDER BY DESC(?weight) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?product a pv:Hardware ;
           pv:name ?name ;
           pv:volume_cm3 ?volume .
  FILTER(CONTAINS(?name, "pontiometer"))
} ORDER BY ASC(?volume) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?coil a pv:Hardware ;
          pv:name ?name ;
          pv:reliabilityIndex ?density .
} ORDER BY DESC(?density) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?email ?phone WHERE {
  ?employee a pv:Employee ;
              pv:name ?name ;
              pv:email ?email ;
              pv:phone ?phone .
  FILTER NOT EXISTS { ?manager pv:hasDirectReport ?employee }
} ORDER BY ?name

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (COUNT(?employee) AS ?employees) WHERE {
  ?department a pv:Department ;
              rdfs:name ?result .
  ?employee a pv:Employee ;
            pv:memberOf ?department .
} GROUP BY ?result HAVING (?employees > 5)

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplier (ROUND(AVG(?amount)) AS ?averagePrice) WHERE {
  ?product pv:hasSupplier ?supplier .
  ?product pv:price ?price .
  ?price pv:currency "EUR" ;
           pv:amount ?amount .
} GROUP BY ?supplier

PREFIX pv: <http://ld.company.org/prod-vocab/>
ASK {
  ?dept a pv:Department .
  FILTER NOT EXISTS { ?dept pv:hasManager ?manager }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplierName ?addressCountry ?addressCountryCode ?addressLocality ?addressText WHERE {
  ?supplier a pv:Supplier ;
            pv:name ?supplierName ;
            pv:addressCountry ?addressCountry ;
            pv:addressCountryCode ?addressCountryCode ;
            pv:addressLocality ?addressLocality ;
            pv:addressText ?addressText .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (COUNT(?product) AS ?products) WHERE {
  ?agent a pv:Employee ;
           pv:areaOfExpertise ?result .
  ?product a pv:Product ;
             pv:hasCategory ?result .
} GROUP BY ?result ORDER BY DESC(?products) LIMIT 3

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?width ?height ?depth WHERE {
  ?result a pv:Hardware ;
            pv:width_mm ?width ;
            pv:height_mm ?height ;
            pv:depth_mm ?depth .
  FILTER(?width > ?height && ?depth < 50)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id ?name WHERE {
  ?hardware a pv:Hardware ;
              pv:id ?id ;
              pv:name ?name .
  FILTER NOT EXISTS { ?hardware pv:hasProductManager ?manager }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?resultA ?resultB WHERE {
  ?resultA pv:compatibleProduct ?resultB .
  ?resultB pv:compatibleProduct ?resultA .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?id ?name ?width WHERE {
  ?result a pv:Hardware ;
            pv:id ?id ;
            pv:name ?name ;
            pv:width_mm ?width .
} ORDER BY DESC(?width) LIMIT 10

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?product a pv:Hardware ;
           pv:hasCategory prodi:prod-cat-Inductor ;
           pv:reliabilityIndex ?reliability ;
           pv:hasSupplier ?supplier .
  FILTER(?reliability = (SELECT MAX(?maxReliability) WHERE {
    ?p a pv:Hardware ;
       pv:hasCategory prodi:prod-cat-Inductor ;
       pv:reliabilityIndex ?maxReliability .
  }))
} ORDER BY DESC(?reliability) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result (COUNT(?product) AS ?products) WHERE {
  ?department a pv:Department ;
              pv:responsibleFor ?product .
} GROUP BY ?department ORDER BY DESC(?products) LIMIT 1
